import{_ as s,o as a,c as o,a2 as i}from"./chunks/framework.Boholvbs.js";const g=JSON.parse('{"title":"Teams & enterprise","description":"PrioriCode in an organization — console accounts and org config, managed system config, MDM on macOS, self-hosted share pages, and the data posture.","frontmatter":{"title":"Teams & enterprise","description":"PrioriCode in an organization — console accounts and org config, managed system config, MDM on macOS, self-hosted share pages, and the data posture."},"headers":[],"relativePath":"platforms/enterprise.md","filePath":"platforms/enterprise.md"}'),t={name:"platforms/enterprise.md"};function r(n,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i(`<p>PrioriCode is honest about its default posture: it runs on <em>your</em> machine with <em>your</em> keys. Everything on this page is the layer for when &quot;your machine&quot; becomes &quot;your fleet.&quot;</p><h2 id="console-accounts" tabindex="-1">Console accounts <a class="header-anchor" href="#console-accounts" aria-label="Permalink to &quot;Console accounts&quot;">​</a></h2><p>The hosted console (<a href="https://prioricode.ai/console" target="_blank" rel="noreferrer">prioricode.ai/console</a>) manages accounts, organizations, and the hosted provider key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # device-code flow: URL + short code in a browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orgs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # your orgs, \`●\` marks the active one</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # change the active org</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # console in the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [email]</span></span></code></pre></div><p>(Yes, it&#39;s a hidden command — <code>console</code> intentionally doesn&#39;t clutter the help. The TUI&#39;s <code>/connect</code> and org-switching dialogs are the day-to-day path.)</p><p>With an active console session two things come automatically:</p><ol><li><strong>Org configuration</strong> — the server&#39;s <code>/api/config</code> for your active org is fetched and merged into every workspace&#39;s config (see <a href="./../configure/files.html">layer 7</a>). Centralize defaults: shared <code>provider</code> blocks through the org gateway, a standard <code>model</code>, baseline <code>permission</code> — one edit, every seat.</li><li><strong>Provider takeover</strong> — the org announces which provider IDs it manages (e.g. an internal gateway), and members inherit credentials/policies for those without pasting keys around. Enterprise SSO and internal AI gateways live here.</li></ol><h2 id="managed-configuration-it-controlled-no-opt-out" tabindex="-1">Managed configuration (IT-controlled, no opt-out) <a class="header-anchor" href="#managed-configuration-it-controlled-no-opt-out" aria-label="Permalink to &quot;Managed configuration (IT-controlled, no opt-out)&quot;">​</a></h2><p>Two enforcement planes that override user and project config:</p><table tabindex="0"><thead><tr><th>Plane</th><th>Location</th><th>Platform</th></tr></thead><tbody><tr><td>Managed config dir</td><td><code>/Library/Application Support/prioricode</code>, <code>%ProgramData%\\prioricode</code>, <code>/etc/prioricode</code> — <code>prioricode.json(c)</code></td><td>macOS, Windows, Linux</td></tr><tr><td>MDM preferences</td><td>domain <code>ai.prioricode.managed</code> (<code>.mobileconfig</code>)</td><td>macOS</td></tr></tbody></table><p>Use them for the non-negotiables: <code>share: disabled</code>, <code>autoupdate</code> pinned, required <code>permission</code> rules, locked <code>disabled_providers</code>. Also worth fleet-spreading as defaults: the <code>hooks</code> and <code>bashSandbox</code> blocks — a PreToolUse hook can enforce policy in any language CI already speaks.</p><h2 id="self-hosted-share-pages" tabindex="-1">Self-hosted share pages <a class="header-anchor" href="#self-hosted-share-pages" aria-label="Permalink to &quot;Self-hosted share pages&quot;">​</a></h2><p><code>/share</code> normally publishes to the hosted service (<code>opncd.ai</code>). Point the whole product at your own deployment:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enterprise&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://shares.acme.dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>The self-hostable app is <code>packages/enterprise</code> in this repo (share pages only — the transcripts stay on users&#39; machines and stream their updates to your deployment). For orgs that must share <em>without</em> leaving the domain: this is the door, and <code>&quot;share&quot;: &quot;disabled&quot;</code> is the wall.</p><h2 id="data-posture-—-the-plain-version" tabindex="-1">Data posture — the plain version <a class="header-anchor" href="#data-posture-—-the-plain-version" aria-label="Permalink to &quot;Data posture — the plain version&quot;">​</a></h2><ul><li><strong>Code and context don&#39;t leave the machine.</strong> Processing is local or direct-to-your-provider API calls. There&#39;s no default telemetry; OpenTelemetry (<code>experimental.openTelemetry</code>, standard <code>OTEL_*</code> env) is opt-in plumbing that exports to <em>your</em> collector.</li><li><strong>The exceptions are explicit</strong>: AI providers (they see prompts by definition — org gateways control which ones), and share links (opt-in, revocable, disableable fleet-wide).</li><li><strong>Credentials</strong>: <code>&lt;data&gt;/auth.json</code>, <code>0600</code>, local. Org-managed providers keep member machines from holding raw keys at all.</li><li><strong>Server mode is user infrastructure</strong>: <code>serve</code>/<code>web</code> default to loopback and say so when unsecured — the network boundary is yours to draw (<a href="./server.html">server</a>).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The repo&#39;s <a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> is the threat model of record: permissions are UX, not isolation; out-of-scope items are enumerated; responsible disclosure goes through GitHub Security Advisories. Enterprise docs claims and this page both defer to it on wording.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../getting-started/providers.html">Providers</a> — OAuth, gateways, and <code>providers login &lt;url&gt;</code>. <ul><li><a href="./../configure/files.html">Config files</a> — Where org/managed config sits in the merge order.</li><li><a href="./../using/sharing.html">Sharing</a> — The share mechanism being self-hosted.</li><li><a href="./github.html">GitHub agent</a> — Org CI running the same agent.</li></ul></li></ul>`,20)])])}const u=s(t,[["render",r]]);export{g as __pageData,u as default};
